function startMenuMusic(){
 if(running){stopMenuMusic();return}if(menuMusicTimer!==null)return;unlockAudio();if(!audioCtx)return;menuMusicStep=0;
 menuMusicGain=audioCtx.createGain();menuMusicGain.gain.value=.72;menuMusicGain.connect(masterGain);
 const chords=[[146.83,174.61,220],[130.81,164.81,196],[110,146.83,174.61],[123.47,155.56,196],[146.83,174.61,220],[164.81,196,246.94],[130.81,164.81,196],[110,146.83,220]];
 const melody=[392,440,523.25,587.33,523.25,440,392,329.63,349.23,392,440,523.25,493.88,440,392,349.23,392,440,523.25,659.25,587.33,523.25,440,392,349.23,392,440,493.88,523.25,587.33,523.25,440];
 const note=(freq,at,dur,wave,vol,attack=.035)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=wave;o.frequency.setValueAtTime(freq,at);g.gain.setValueAtTime(.0001,at);g.gain.linearRampToValueAtTime(vol,at+attack);g.gain.setTargetAtTime(.0001,at+Math.max(attack,dur*.68),Math.max(.025,dur*.18));o.connect(g);g.connect(menuMusicGain);o.start(at);o.stop(at+dur)};
 const phrase=()=>{if(!audioCtx||!menuMusicGain||audioCtx.state!=='running')return;const now=audioCtx.currentTime,step=menuMusicStep%32,bar=Math.floor(step/4)%8,beat=step%4,root=chords[bar];
  if(beat===0){root.forEach((f,k)=>{note(f/2,now,2.1,'triangle',k===0?.16:.105,.12);note(f,now,1.65,'sawtooth',.045,.16)});note(root[0]/2,now,1.4,'sine',.2,.08)}
  const f=melody[step];note(f,now,.47,'triangle',.16,.025);if(step%2===0)note(f*2,now,.22,'sine',.045,.012);
  const bass=[55,55,65.41,73.42,49,49,55,65.41][bar];note(bass,now,.38,'sawtooth',.21,.012);
  if(beat===0||beat===2){note(68,now,.2,'sine',.22,.004);note(42,now,.16,'triangle',.11,.003)}
  if(beat===1||beat===3){note(190,now,.09,'triangle',.07,.003);note(1250,now,.045,'sawtooth',.018,.002)}
  menuMusicStep++;};
 phrase();menuMusicTimer=setInterval(phrase,300);
}
// Start preparing the soundtrack as soon as the game module loads. Browsers may wait for the first user gesture before allowing audible playback.
startMenuMusic();
