function announce(line,priority='normal'){return;/* all voice and announcer audio disabled */

 const messages={'Prepare for battle.':'전투 준비. 전투가 곧 시작됩니다.','Red team has successfully defended the stage!':'레드 팀이 거점을 방어했습니다.','Control points captured! Blue team wins the stage!':'블루 팀이 거점을 점령했습니다. 블루 팀 승리.','The match is a draw!':'무승부입니다.','Victory! Red team wins the match!':'레드 팀이 승리했습니다.','Defeat! Blue team wins the match!':'블루 팀이 승리했습니다.','Control point A has been captured!':'A 거점이 점령되었습니다.','Control point B has been captured!':'B 거점이 점령되었습니다.','The gates are open! Move out!':'출격하십시오. 전투 구역이 개방되었습니다.','Thirty seconds remaining!':'남은 시간 30초.','Ten seconds remaining!':'남은 시간 10초.','Five seconds remaining!':'남은 시간 5초.','One!':'하나!'};
 let clean=String(line);for(const [en,ko] of Object.entries(messages))clean=clean.replace(en,ko);
 clean=clean.replace(/Stage (\d+)/gi,'스테이지 $1').replace(/Defend the control points\./gi,'거점을 방어하십시오.').replace(/Capture the control points\./gi,'거점을 점령하십시오.').replace(/Control point ([AB]) has been captured!/gi,'$1 거점이 점령되었습니다.');
 clean=clean.replace(/[^가-힣ㄱ-ㅎㅏ-ㅣA-Z0-9 .,!?:·'-]/g,' ').replace(/\s+/g,' ').trim();if(!clean)return;
 try{if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(clean);u.lang='ko-KR';u.rate=priority==='urgent'?1.12:1.06;u.pitch=priority==='urgent'?1.2:1.14;u.volume=1;const voices=speechSynthesis.getVoices();const v=voices.find(x=>/^ko[-_]KR/i.test(x.lang)&&/남|민준|인준|Male|Hyun|Jinho/i.test(x.name))||voices.find(x=>/^ko[-_]KR/i.test(x.lang));if(v)u.voice=v;speechSynthesis.speak(u)}}catch(e){}
 playSfx('announce',null,.2);
}

