function rebuildBotModelForRespawn(b){if(b.burnMesh&&b.mesh){b.mesh.remove(b.burnMesh);b.burnMesh=null}if(b.mesh){scene.remove(b.mesh);b.mesh.traverse(o=>{if(o.isMesh){o.geometry?.dispose?.();if(Array.isArray(o.material))o.material.forEach(m=>m?.dispose?.());else o.material?.dispose?.()}});b.mesh=null}buildBotModel(b);b.mesh.visible=true;b.mesh.rotation.set(0,0,0);b.mesh.scale.set(1,1,1);b.mesh.position.copy(b.pos);b.mesh.traverse(o=>{if(o.isMesh)o.visible=true})}
function buildBotModel(b){const g=new THREE.Group(),shirt=b.cls.id==='medic'?M.white:(b.side==='red'?M.red:M.blue),skin=M.skin,id=b.cls.id;
box(g,0,.82,0,id==='heavy'?1.05:.72,1.05,id==='heavy'?.65:.43,shirt);box(g,-.2,.22,0,.23,.45,.27,M.black);box(g,.2,.22,0,.23,.45,.27,M.black);box(g,0,1.55,0,.52,.5,.48,id==='spy'?M.black:skin);
if(id==='scout'){const cap=mat(b.side==='red'?0x9d3029:0x315f8e),capDark=mat(b.side==='red'?0x68231f:0x203e60),strap=mat(0x24282c),bag=mat(0x35383a);/* baseball cap */box(g,0,1.84,-.015,.64,.17,.58,cap);box(g,0,1.76,.24,.62,.055,.38,capDark);box(g,0,1.79,.34,.48,.045,.22,cap);/* headset band and ear cups */const band=new THREE.Mesh(new THREE.TorusGeometry(.29,.035,6,18,Math.PI),mat(0x25292c));band.rotation.x=Math.PI/2;band.position.set(0,1.65,-.015);g.add(band);box(g,-.29,1.58,.015,.12,.2,.13,strap);box(g,.29,1.58,.015,.12,.2,.13,strap);box(g,.31,1.51,.09,.07,.07,.1,M.metal);/* diagonal shoulder-to-waist strap */const diagonal=box(g,.02,1.13,.235,.12,.83,.055,strap);diagonal.rotation.z=-.48;/* small messenger bag at hip/back */box(g,-.27,.79,-.22,.38,.43,.23,bag);box(g,-.27,.83,-.095,.27,.2,.035,strap);box(g,-.27,.69,-.09,.1,.055,.035,M.metal)}
if(id==='soldier'){box(g,0,1.86,0,.67,.18,.64,mat(0x59666b));box(g,0,1.97,0,.36,.09,.34,M.dark)}
if(id==='pyro'){box(g,0,1.55,.28,.55,.35,.18,M.black);for(const x of [-.2,.2])ball(g,x,1.62,.39,.065,M.gold);box(g,-.48,.95,-.05,.18,.75,.25,M.metal);box(g,-.48,1.35,-.05,.22,.25,.28,M.gold)}
if(id==='demoman'){box(g,.18,1.57,.25,.14,.1,.08,M.black);box(g,0,1.84,0,.66,.17,.65,mat(0x343b3d))}
if(id==='heavy'){box(g,0,1.48,.26,.75,.25,.15,M.skin);box(g,-.48,1,-.03,.28,.7,.35,M.metal)}
if(id==='engineer'){box(g,0,1.85,0,.7,.16,.66,mat(0xd39b36));box(g,0,1.98,0,.3,.1,.3,M.dark)}
if(id==='medic'){box(g,0,1.82,0,.66,.15,.6,M.white);box(g,0,1.02,-.31,.45,.6,.2,M.white);box(g,0,1.02,-.42,.16,.16,.04,M.red)}
if(id==='sniper'){box(g,0,1.85,0,.68,.13,.62,mat(0x7a8b68));box(g,.24,1.56,.27,.22,.12,.08,M.black)}
if(id==='spy'){box(g,0,1.57,.26,.4,.25,.09,M.black);box(g,0,1.85,0,.68,.12,.6,mat(0x262b32))}
if(['soldier','demoman'].includes(id)){box(g,.42,1.04,.38,.24,.24,.85,M.metal);box(g,.42,1.04,.78,.18,.18,.38,M.black)}
else if(id==='heavy'){box(g,.43,1.1,.42,.38,.28,.6,M.metal);for(const x of [.3,.4,.5,.6])box(g,x,1.1,.8,.055,.055,.65,M.black)}
else if(id==='sniper'){box(g,.4,1.1,.4,.13,.13,1.15,M.black);box(g,.4,1.2,.25,.18,.1,.24,M.gold)}
else if(id==='pyro'){box(g,.42,1.03,.4,.3,.28,.58,M.metal);box(g,.42,1.04,.8,.2,.2,.42,M.black)}
else if(id==='medic'){box(g,.42,1.05,.35,.22,.22,.5,M.white);box(g,.42,1.05,.65,.13,.13,.25,M.red)}
else box(g,.4,1.05,.35,.19,.18,.42,id==='spy'?M.black:M.metal);
g.position.copy(b.pos);scene.add(g);b.mesh=g}
function updateHomePreview(c,selected=false){if(!c)return;if(homePreviewModel)homePreviewScene.remove(homePreviewModel);const dummy={cls:c,side:$('.team.active')?.dataset.team||team||'red',pos:new THREE.Vector3(0,0,0),mesh:null};buildBotModel(dummy);scene.remove(dummy.mesh);homePreviewModel=dummy.mesh;homePreviewModel.position.set(0,0,0);homePreviewScene.add(homePreviewModel);homePreviewClassId=c.id;$('#homePreviewName').textContent=selected?c.name:'SELECT A CLASS';$('#homePreviewRole').textContent=selected?c.desc:'CHOOSE A CLASS TO PREVIEW';$('#homePreviewHp').textContent=c.hp+' HP';$('#homePreviewWeapons').textContent=c.weapons.map(w=>w.name).join('  / ')}
function spawnBot(i,side){const c=CLASSES[Math.floor(i/2)%CLASSES.length],b={id:i,side,role:side==='blue'?'attacker':'defender',cls:c,hp:c.hp,max:c.hp,pos:new THREE.Vector3(side==='red'?96-Math.random()*5:-96+Math.random()*5,0,(Math.random()-.5)*8),alive:true,cd:Math.random(),respawn:0,mesh:null,nextRoleAction:1+Math.random()*3,disguiseUntil:0,flankSide:i%2?1:-1,ammoPct:.92+Math.random()*.08};buildBotModel(b);return b}
function makeBots(){for(const b of bots)scene.remove(b.mesh);bots=[];for(let i=0;i<18;i++)bots.push(spawnBot(i,i%2?'blue':'red'));for(const b of bots){b.navPath=null;b.navGoal=null;b.navIndex=0;b.jumpY=0;b.jumpVy=0}}
function say(t,ms=1400){const e=$('.center-message');e.textContent=t;e.style.opacity='1';clearTimeout(say.timer);say.timer=setTimeout(()=>e.style.opacity='0',ms)}
function feed(t){const el=$('.killfeed'),n=document.createElement('div');n.className='feed';n.textContent=t;el.prepend(n);while(el.children.length>4)el.lastChild.remove();setTimeout(()=>n.remove(),4300)}
function teamChat(speaker,message,side=team,kind='voice'){
 const host=$('#teamChat');if(!host)return;
 const row=document.createElement('div');row.className='team-chat-line '+(side==='red'?'red-chat':'blue-chat')+(kind==='player'?' player-chat':'');
 const who=document.createElement('b');who.textContent=speaker;
 const msg=document.createElement('span');msg.textContent=message;
 row.append(who,msg);host.prepend(row);
 while(host.children.length>5)host.lastChild.remove();
 setTimeout(()=>row.classList.add('fading'),5700);setTimeout(()=>row.remove(),6500);
}
function callForMedic(){
 if(clock-lastMedicCall<1.1){return}
 lastMedicCall=clock;playerMedicCallUntil=clock+9;
 teamChat('YOU','메딕! 치료가 필요하다!',team,'player');
 say('MEDIC! · 아군 메딕에게 지원 요청',1100);
 const nearest=bots.filter(b=>b.alive&&b.side===team&&b.cls.id==='medic').sort((a,b)=>a.pos.distanceTo(player)-b.pos.distanceTo(player))[0];
 if(nearest)teamChat(nearest.cls.ko.toUpperCase(),'요청 확인! 지금 간다!',team,'voice');
}
function aimedBuilding(){const dir=new THREE.Vector3(0,0,-1).applyEuler(camera.rotation).normalize();return buildings.filter(b=>b.side===team&&player.distanceTo(b.pos)<13).map(b=>({b,d:b.pos.clone().add(new THREE.Vector3(0,1,0)).sub(camera.position),distance:player.distanceTo(b.pos)})).filter(x=>x.d.normalize().dot(dir)>.985).sort((x,z)=>x.distance-z.distance)[0]?.b||null}
function updateAimTarget(){const info=$('#targetInfo');if(!info)return;const dir=new THREE.Vector3(0,0,-1).applyEuler(camera.rotation).normalize();let best=null,bestDist=Infinity;if(cls.id==='engineer'){for(const b of buildings){if(b.side!==team)continue;const delta=b.pos.clone().add(new THREE.Vector3(0,1,0)).sub(camera.position),dist=delta.length();if(dist<16&&delta.normalize().dot(dir)>.982&&dist<bestDist){best={type:'building',item:b};bestDist=dist}}}if(cls.id==='medic'){for(const b of bots){if(!b.alive||b.side!==team)continue;const delta=b.pos.clone().add(new THREE.Vector3(0,1,0)).sub(camera.position),dist=delta.length();if(dist<25&&delta.normalize().dot(dir)>.986&&dist<bestDist){best={type:'ally',item:b};bestDist=dist}}}if(best){const b=best.item;info.style.display='block';info.innerHTML=best.type==='building'?'<b>'+b.kind.toUpperCase().replace('TELEPORTERENTRANCE','TELEPORTER ENTRANCE').replace('TELEPORTEREXIT','TELEPORTER EXIT')+'</b><span>LEVEL '+b.level+' · HP '+Math.ceil(b.hp)+' / '+b.maxHp+'</span><div class="ally-health-track"><i style="width:'+Math.max(0,b.hp/b.maxHp*100)+'%;background:'+(b.hp/b.maxHp<.35?'#e34c43':'#77c96b')+'"></i></div>'+(cls.id==='engineer'&&wi===2?(b.hp<b.maxHp?'<small>렌치 클릭: '+Math.min(40,b.maxHp-b.hp)+' HP 수리 · 철제 '+Math.ceil(Math.min(40,b.maxHp-b.hp)/2)+'</small>':b.level<3?'<small>렌치 클릭: 업그레이드 · 철제 200</small>':'<small>최대 레벨 · 렌치로 수리 가능</small>'):''):'<b>'+b.cls.ko.toUpperCase()+'</b><span>ALLY HEALTH · '+Math.ceil(b.hp)+' / '+b.max+'</span><div class="ally-health-track"><i style="width:'+Math.max(0,b.hp/b.max*100)+'%"></i></div>'}else info.style.display='none'}
function updateWeaponSidebar(){const el=$('#weaponSidebar');if(!el)return;let a=cls.weapons.map((w,i)=>'<div class="weapon-slot '+(i===wi?'active':'')+'"><b>'+(i+1)+'</b><strong>'+w.name+'</strong><small>'+(({shotgun:'SHOTGUN',rocket:'EXPLOSIVE',flame:'FLAME THROWER',sniper:'SNIPER RIFLE',heal:'MEDIGUN',melee:'MELEE',pda:'PDA',bullet:'FIREARM',syringe:'SYRINGE GUN',grenade:'GRENADE LAUNCHER',sticky:'STICKY LAUNCHER'})[w.kind]||'WEAPON')+'</small></div>');if(cls.id==='engineer')a.push('<div class="weapon-slot utility-slot '+(specialMode==='build'?'active':'')+'"><b>4</b><strong>건설 도구</strong><small>BUILD PDA</small></div>','<div class="weapon-slot utility-slot '+(specialMode==='destroy'?'active':'')+'"><b>5</b><strong>철거 도구</strong><small>DESTROY PDA</small></div>');if(cls.id==='spy')a.push('<div class="weapon-slot utility-slot '+(specialMode==='sapper'?'active':'')+'"><b>3</b><strong>전자 교란기</strong><small>SAPPER · ENEMY BUILDINGS</small></div>','<div class="weapon-slot utility-slot '+(specialMode==='disguise'?'active':'')+'"><b>4</b><strong>변장 도구</strong><small>DISGUISE PDA</small></div>');el.innerHTML=a.join('')}
