document.addEventListener('pointerlockchange',()=>locked=document.pointerLockElement===renderer.domElement);renderer.domElement.addEventListener('click',()=>{if(running&&!locked)renderer.domElement.requestPointerLock()});
document.addEventListener('mousemove',e=>{if(!locked||!running)return;yaw-=e.movementX*.0022;pitch=Math.max(-1.48,Math.min(1.48,pitch-e.movementY*.0022));camera.rotation.order='YXZ';camera.rotation.set(pitch,yaw,0)});
document.addEventListener('keydown',e=>{if(e.repeat&&['Space','Digit1','Digit2','Digit3','Digit4','Digit5','KeyE'].includes(e.code))return;keys[e.code]=true;if(e.code==='KeyE'&&running){e.preventDefault();callForMedic()}if(e.code==='KeyX'&&running&&specialMode){e.preventDefault();specialMode='';if(cls.id==='engineer'){wi=0;ammo=ammoState[0]??weapon().ammo;reserve=reserveState[0]??weapon().reserve}buildViewWeapon();updatePda();updateHud();say('PDA CLOSED · PRIMARY WEAPON',650)}if(e.code==='Tab'&&running){e.preventDefault();renderScoreboard();$('#scoreboard').style.display='flex'}if(e.code==='Escape'&&running){if(specialMode){specialMode='';updatePda();buildViewWeapon()}else pause()}if(e.code==='KeyR'&&running)reload();if(e.code==='KeyQ'&&running)activateAbility();if(e.code==='Space'&&running){e.preventDefault();jumpPressed=true}
if(running&&specialMode==='disguise'&&/^Digit[1-9]$/.test(e.code)){const names=['SCOUT','SOLDIER','PYRO','DEMOMAN','HEAVY','ENGINEER','MEDIC','SNIPER','SPY'];spyDisguiseSide=team==='red'?'blue':'red';spyDisguiseClass=names[Number(e.code.slice(-1))-1];specialMode='';updatePda();say('DISGUISED AS '+spyDisguiseSide.toUpperCase()+' '+spyDisguiseClass,1000);updateHud();return}
if(e.code==='Digit1'&&running){if(carriedBuilding){say('상자를 먼저 설치하세요',600);return}if(specialMode==='build')chooseBuild('sentry');else if(specialMode==='destroy'){buildChoice='sentry';updatePda()}else switchWeapon(0)}
if(e.code==='Digit2'&&running){if(carriedBuilding){say('상자를 먼저 설치하세요',600);return}if(specialMode==='build')chooseBuild('dispenser');else if(specialMode==='destroy'){buildChoice='dispenser';updatePda()}else switchWeapon(1)}
if(e.code==='Digit3'&&running){if(carriedBuilding){say('상자를 먼저 설치하세요',600);return}else if(cls.id==='spy'&&!specialMode){setSpecial('sapper')}else if(specialMode==='build')chooseBuild('teleporterEntrance');else if(specialMode==='destroy'){buildChoice='teleporter';updatePda()}else switchWeapon(2)}
if(e.code==='Digit4'&&running&&cls.id==='engineer'&&carriedBuilding)say('상자를 먼저 설치하세요',600);else if(e.code==='Digit4'&&running&&cls.id==='engineer'&&specialMode==='build')chooseBuild('teleporterExit');else if(e.code==='Digit4'&&running&&cls.id==='engineer'&&specialMode==='destroy'){buildChoice='all';updatePda()}else if(e.code==='Digit4'&&running&&cls.id==='engineer')setSpecial('build');
if(e.code==='Digit4'&&running&&cls.id==='spy')setSpecial('disguise');if(e.code==='Digit5'&&running&&cls.id==='engineer'&&!carriedBuilding)setSpecial('destroy');else if(e.code==='Digit5'&&running&&cls.id==='engineer'&&carriedBuilding)say('상자를 먼저 설치하세요',600);
if(e.code==='Comma'&&!e.repeat&&running){e.preventDefault();classChangeMode=true;running=false;$('#pause').style.display='none';$('#hud').style.display='none';$('#homeScreen').style.display='none';$('#menu').style.display='flex';document.exitPointerLock?.()}});
document.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='Space')jumpPressed=false;if(e.code==='Tab')$('#scoreboard').style.display='none'});
// Reliable movement input: keep WASD/arrow/jump state in sync even after overlays or pointer-lock changes.
window.addEventListener('keydown',e=>{if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','ShiftLeft','ShiftRight'].includes(e.code)){if(e.code==='Space'&&running){e.preventDefault();jumpPressed=true}keys[e.code]=true}},{capture:true});
window.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='Space')jumpPressed=false},{capture:true});
window.addEventListener('blur',()=>{for(const k of ['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','ShiftLeft','ShiftRight'])keys[k]=false;jumpPressed=false});
window.addEventListener('keydown',e=>{const key=String(e.key||'').toLowerCase();const code=e.code||({'w':'KeyW','a':'KeyA','s':'KeyS','d':'KeyD',' ':'Space','arrowup':'ArrowUp','arrowdown':'ArrowDown','arrowleft':'ArrowLeft','arrowright':'ArrowRight','shift':'ShiftLeft'}[key]);if(!code)return;const movement=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','ShiftLeft','ShiftRight'];if(movement.includes(code)){keys[code]=true;if(running)e.preventDefault()}if(code==='Space'&&running){keys.Space=true;jumpPressed=true;e.preventDefault()}if(running&&!e.repeat&&/^Digit[1-5]$/.test(code)){const slot=Number(code.slice(-1));if(slot<=3&&!specialMode){e.preventDefault();switchWeapon(slot-1)}else if(slot===4&&cls.id==='engineer'&&!specialMode){e.preventDefault();setSpecial('build')}else if(slot===5&&cls.id==='engineer'&&!specialMode){e.preventDefault();setSpecial('destroy')}}},true);
window.addEventListener('keyup',e=>{const key=String(e.key||'').toLowerCase();const code=e.code||({'w':'KeyW','a':'KeyA','s':'KeyS','d':'KeyD',' ':'Space','arrowup':'ArrowUp','arrowdown':'ArrowDown','arrowleft':'ArrowLeft','arrowright':'ArrowRight','shift':'ShiftLeft'}[key]);if(code)keys[code]=false;if(code==='Space')jumpPressed=false},true);

document.addEventListener('mousedown',e=>{if(e.target.closest?.('.pda-panel'))return;if(e.button===0){keys.Mouse0=true;if(running&&locked)shoot()}if(e.button===2&&running){if(cls.id==='sniper'){sniperCharging=true;sniperCharge=0;aiming=true;camera.fov=34;camera.updateProjectionMatrix();document.body.classList.add('scoped')}else if(cls.id==='spy'){if(clock>=spyCloakCd){spyCloakUntil=clock+7;spyCloakCd=clock+15;document.body.classList.add('cloaked');say('CLOAK ACTIVE · 7 SECONDS',800)}else say('CLOAK RECHARGING · '+Math.ceil(spyCloakCd-clock)+'s',700)}else if(cls.id==='demoman')detonateStickies();else if(cls.id==='pyro')activateAbility();else if(cls.id==='engineer'){if(!carriedBuilding&&aimedBuilding())pickupBuilding();else if(carriedBuilding)say('왼쪽 클릭으로 구조물을 설치하세요',700)}}});
document.addEventListener('mouseup',e=>{if(e.button===0)keys.Mouse0=false;if(e.button===2){sniperCharging=false;if(aiming){aiming=false;camera.fov=76;camera.updateProjectionMatrix();document.body.classList.remove('scoped')}}});
document.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('wheel',e=>{if(running){e.preventDefault();switchWeapon((wi+(e.deltaY>0?1:2))%3)}},{passive:false});
function switchWeapon(n){if(carriedBuilding){say('구조물을 설치한 뒤 무기를 전환할 수 있습니다',750);return}if(n===wi||!cls.weapons[n])return;ammoState[wi]=ammo;reserveState[wi]=reserve;wi=n;ammo=ammoState[wi]??weapon().ammo;reserve=reserveState[wi]??weapon().reserve;reloading=false;reloadUntil=0;buildViewWeapon();updateHud()}
function reload(){const w=weapon();if(reloading||['melee','heal','pda'].includes(w.kind)||ammo>=w.clip||reserve<=0)return;reloading=true;playSfx('reload',player,.38);reloadUntil=clock+(w.kind==='sniper'?1.45:['rocket','grenade','sticky'].includes(w.kind)?1.25:.9);say('RELOADING',650)}
function finishReload(){const take=Math.min(weapon().clip-ammo,reserve);ammo+=take;reserve-=take;ammoState[wi]=ammo;reserveState[wi]=reserve;reloading=false;reloadUntil=0;buildViewWeapon();updateHud()}
function spawnBlood(pos,count=7){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.SphereGeometry(.045+Math.random()*.045,5,4),mat(i%3?0x8d1118:0xc51d27));mesh.position.copy(pos);scene.add(mesh);bloodParticles.push({mesh,vel:new THREE.Vector3((Math.random()-.5)*5,1+Math.random()*4,(Math.random()-.5)*5),life:.28+Math.random()*.3})}}
function makeCorpseGray(mesh){const gray=new THREE.MeshStandardMaterial({color:0x777b7d,roughness:.92,metalness:.02});mesh.traverse(o=>{if(o.isMesh){o.material=gray;o.castShadow=true;o.receiveShadow=true}})}
function spawnPlayerCorpse(){const body={id:-1,side:team,cls,hp:0,max:cls.hp,pos:player.clone(),alive:false};buildBotModel(body);makeCorpseGray(body.mesh);body.mesh.rotation.z=Math.random()<.5?1.35:-1.35;body.vel=new THREE.Vector3((Math.random()-.5)*3,2,(Math.random()-.5)*3);body.life=4.5;ragdollBodies.push(body)}
function spawnGibs(pos,side,count=9){const tm=side==='red'?M.red:M.blue;for(let i=0;i<count;i++){const mesh=new THREE.Mesh(i%2?new THREE.BoxGeometry(.16+Math.random()*.2,.12+Math.random()*.2,.14+Math.random()*.2):new THREE.SphereGeometry(.11+Math.random()*.1,6,5),i%3?tm:M.skin);mesh.position.copy(pos).add(new THREE.Vector3((Math.random()-.5)*.7,.4+Math.random()*1.2,(Math.random()-.5)*.7));scene.add(mesh);gibParticles.push({mesh,vel:new THREE.Vector3((Math.random()-.5)*11,3+Math.random()*8,(Math.random()-.5)*11),spin:new THREE.Vector3(Math.random()*8,Math.random()*8,Math.random()*8),life:1.6+Math.random()*1.1})}}
function killBot(b,attacker='YOU',explosive=false){if(!b.alive)return;b.burnUntil=0;b.burnNext=0;if(b.burnMesh){b.mesh.remove(b.burnMesh);b.burnMesh=null}b.hp=0;b.alive=false;b.respawn=5+Math.random()*3;b.ragdollVel=new THREE.Vector3((Math.random()-.5)*3,2,(Math.random()-.5)*3);if(explosive){spawnGibs(b.pos,b.side,11);b.mesh.visible=false}else{b.mesh.visible=true;makeCorpseGray(b.mesh);b.mesh.rotation.set((Math.random()-.5)*.25,b.mesh.rotation.y,Math.random()<.5?1.35:-1.35)}feed(attacker+' ✕ '+b.cls.name+' ['+b.side.toUpperCase()+']');if(b.side!==team)health=Math.min(cls.hp,health+8);updateHud()}
function hurtBot(b,d,attacker='YOU',explosive=false){if(!b.alive)return;if(setupRemaining>0)return;b.hp-=d;spawnBlood(b.pos.clone().add(new THREE.Vector3((Math.random()-.5)*.4,1.1+Math.random()*.5,(Math.random()-.5)*.4)),6);playSfx('impact',b.pos,.22);const h=$('.hitmarker');h.classList.add('show');setTimeout(()=>h.classList.remove('show'),90);if(b.hp<=0){playSfx('death',b.pos,.34);killBot(b,attacker,explosive)}}
function harmPlayer(d,explosive=false){if(spectatorTimer>0)return;if(setupRemaining>0&&insideTeamBase(player.x,player.z,team))return;if(clock<heavyGuardUntil)d*=.48;if(clock<medicUberUntil)d=0;spawnBlood(player.clone().add(new THREE.Vector3((Math.random()-.5)*.5,1.2+Math.random()*.45,(Math.random()-.5)*.5)),5);playSfx('impact',player,.3);health-=d;document.body.classList.add('damaged');clearTimeout(harmPlayer.flash);harmPlayer.flash=setTimeout(()=>document.body.classList.remove('damaged'),170);if(health<=0){playSfx('death',player,.55);deathCount++;feed('YOU WERE ELIMINATED');if(explosive)spawnGibs(player.clone().add(new THREE.Vector3(0,1,0)),team,12);else spawnPlayerCorpse();respawn()}updateHud()}
function makeProjectile(origin,dir,owner,damage,speed,radius,side,kind='normal'){
 const sticky=kind==='sticky',projectileColor=sticky?0x343b42:kind==='syringe'?0xb7f5e6:owner==='player'?0xffb64c:side==='red'?0xf46d4e:0x69b9ff,mesh=new THREE.Mesh(new THREE.SphereGeometry(sticky?.24:.17,sticky?12:8,8),mat(projectileColor));
 mesh.position.copy(origin);if(sticky){const ring=new THREE.Mesh(new THREE.TorusGeometry(.24,.045,6,12),mat(0xe4c75b));ring.rotation.x=Math.PI/2;mesh.add(ring)}
 scene.add(mesh);projectiles.push({mesh,dir:dir.clone(),owner,damage,speed,radius,side,kind,life:kind==='sticky'?18:kind==='grenade'?3.5:3.4,gravity:['sticky','grenade'].includes(kind)?.22:0,stuck:false})
}
function applyPlayerBurn(){playerBurnUntil=clock+3.2;playerBurnNext=Math.min(playerBurnNext||0,clock);document.body.classList.add('burning')}
function applyBurn(b){b.burnUntil=clock+3.4;b.burnNext=clock+.45;if(!b.burnMesh){const fire=new THREE.Mesh(new THREE.ConeGeometry(.22,.7,7),mat(0xff6a22));fire.position.set(0,1.7,0);b.mesh.add(fire);b.burnMesh=fire}}
function detonateStickies(){const mines=projectiles.filter(p=>p.kind==='sticky'&&p.owner==='player');if(!mines.length){say('NO STICKY BOMBS DEPLOYED',650);return}for(const p of mines){const pos=p.mesh.position.clone();playSfx('explosion',pos,.5);spawnExplosionVisual(pos,team==='red'?0xff7042:0x5caaff,Math.max(1.8,p.radius*.9));for(const bot of bots)if(bot.alive&&bot.side!==team){const d=bot.pos.distanceTo(pos);if(d<p.radius)hurtBot(bot,p.damage*Math.max(.15,1-d/p.radius),'STICKY TRAP',true)}for(const b of [...buildings])if(b.side!==team){const d=b.pos.distanceTo(pos);if(d<p.radius)damageBuilding(b,p.damage*Math.max(.15,1-d/p.radius),team.toUpperCase())}const pd=player.distanceTo(pos);if(pd<p.radius)harmPlayer(p.damage*Math.max(.15,1-pd/p.radius)*.75,true);scene.remove(p.mesh);const index=projectiles.indexOf(p);if(index>=0)projectiles.splice(index,1)}say('STICKY BOMBS DETONATED',450);updateHud()}
function setSpecial(mode){specialMode=specialMode===mode?'':mode;if(mode==='build')buildChoice='sentry';if(mode==='destroy')buildChoice='sentry';buildViewWeapon();updatePda();say(specialMode?mode.toUpperCase()+' PDA · SELECT WITH NUMBER KEYS':'PDA CLOSED',800);updateHud()}
function updatePda(){const b=$('#buildPda'),d=$('#destroyPda'),p=$('#disguisePda');if(b)b.style.display=specialMode==='build'?'flex':'none';if(d)d.style.display=specialMode==='destroy'?'flex':'none';if(p)p.style.display=specialMode==='disguise'?'grid':'none';document.querySelectorAll('[data-build]').forEach(el=>{const k=el.dataset.build,exists=buildings.some(x=>x.side===team&&!Number.isFinite(x.builtBy)&&x.kind===k),cost=({sentry:130,dispenser:100,teleporterEntrance:50,teleporterExit:50})[k]||0;el.classList.toggle('selected',k===buildChoice);el.disabled=exists;const st=el.querySelector('strong'),sm=el.querySelector('small');if(st)st.textContent=exists?'설치됨':k.toUpperCase().replace('TELEPORTER','TELEPORTER ');if(sm)sm.textContent=exists?'이미 설치한 구조물':'설치 비용 '+cost+' METAL'});document.querySelectorAll('[data-destroy]').forEach(el=>el.classList.toggle('selected',el.dataset.destroy===buildChoice));const ml=$('#metalAmount');if(ml)ml.textContent=metal+' / 200';const mf=$('#buildMetal');if(mf)mf.textContent='보유 철제: '+metal+' / 200 · 업그레이드: 200 METAL'}
function chooseBuild(kind){buildChoice=kind;updatePda();say('SELECTED · '+kind.toUpperCase(),500)}
document.querySelectorAll('[data-build]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();chooseBuild(el.dataset.build)}));
document.querySelectorAll('[data-destroy]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();buildChoice=el.dataset.destroy;updatePda();say('DESTROY · '+buildChoice.toUpperCase(),500)}));
document.querySelectorAll('[data-disguise]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();spyDisguiseSide=team==='red'?'blue':'red';spyDisguiseClass=el.dataset.disguise;specialMode='';updatePda();say('DISGUISED AS '+spyDisguiseSide.toUpperCase()+' '+spyDisguiseClass,900);updateHud()}));
function makeCarryBox(){if(carryBoxMesh)camera.remove(carryBoxMesh);carryBoxMesh=new THREE.Group();const dark=mat(0x343a40,.55),metalMat=mat(0x77838a,.4),accent=mat(team==='red'?0xb84b40:0x3e7eb9,.35);box(carryBoxMesh,0,0,0,.48,.48,.48,dark);box(carryBoxMesh,0,0,.25,.3,.3,.035,metalMat);for(const x of [-.18,.18])for(const y of [-.18,.18])box(carryBoxMesh,x,y,.255,.055,.055,.025,accent);carryBoxMesh.position.set(.38,-.34,-.85);camera.add(carryBoxMesh)}
function pickupBuilding(){const b=aimedBuilding();if(!b){say('조준한 아군 구조물이 없습니다',800);return}if(carriedBuilding){say('이미 구조물을 들고 있습니다',800);return}carriedBuilding=b;b.mesh.visible=false;makeCarryBox();buildViewWeapon();updateWeaponSidebar();say('구조물 이동 중 · 상자만 운반 · 왼쪽 클릭으로 설치',1200);updateAimTarget()}
function placeCarriedBuilding(){if(!carriedBuilding)return;const dir=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw)),pos=player.clone().addScaledVector(dir,3);if(blocked(pos.x,pos.z)||Math.abs(pos.x)>106||Math.abs(pos.z)>75||buildings.some(b=>b!==carriedBuilding&&b.pos.distanceTo(pos)<2.8)){say('여기에는 설치할 수 없습니다',850);return}carriedBuilding.pos.set(pos.x,0,pos.z);carriedBuilding.mesh.position.set(pos.x,0,pos.z);carriedBuilding.mesh.visible=true;carriedBuilding.next=clock;carriedBuilding=null;if(carryBoxMesh){camera.remove(carryBoxMesh);carryBoxMesh=null}buildViewWeapon();say('구조물 이동 완료',800);updatePda();updateHud()}
function placeBuilding(){const dir=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw)),pos=player.clone().addScaledVector(dir,3);if(blocked(pos.x,pos.z)||Math.abs(pos.x)>106||Math.abs(pos.z)>75){say('CANNOT BUILD HERE',800);return}if(buildings.some(b=>b.pos.distanceTo(pos)<2.8)){say('TOO CLOSE TO ANOTHER BUILDING',900);return}const kind=buildChoice,owned=buildings.filter(b=>b.side===team&&!Number.isFinite(b.builtBy)),isTele=kind.startsWith('teleporter'),buildCost=({sentry:130,dispenser:100,teleporterEntrance:50,teleporterExit:50})[kind]||0;if(owned.some(b=>b.kind===kind)){say('STRUCTURE ALREADY BUILT',850);updatePda();return}if(metal<buildCost){say('NOT ENOUGH METAL · NEED '+buildCost,1000);return}if(kind==='sentry'&&owned.some(b=>b.kind==='sentry')){say('ONLY ONE SENTRY ALLOWED',850);return}if(kind==='dispenser'&&owned.some(b=>b.kind==='dispenser')){say('ONLY ONE DISPENSER ALLOWED',850);return}if(isTele&&owned.some(b=>b.kind===kind)){say('ONLY ONE OF EACH TELEPORTER PAD',850);return}const g=new THREE.Group();g.position.set(pos.x,0,pos.z);const color=team==='red'?M.red:M.blue;if(kind==='sentry'){box(g,0,.35,0,1.35,.7,1.15,M.dark);box(g,0,.88,0,.88,.42,.8,color);box(g,0,1.2,-.15,.45,.2,.45,M.metal);for(const x of [-.22,0,.22])box(g,x,.9,.43,.09,.09,.2,M.gold)}else if(kind==='dispenser'){box(g,0,.65,0,1.15,1.3,.95,M.dark);box(g,0,.95,.51,.75,.38,.08,color);box(g,0,.35,.51,.45,.12,.08,M.gold)}else{const pad=new THREE.Mesh(new THREE.CylinderGeometry(.8,.8,.22,16),M.metal);pad.position.y=.12;g.add(pad);const ring=new THREE.Mesh(new THREE.TorusGeometry(.65,.08,8,20),M.gold);ring.rotation.x=Math.PI/2;ring.position.y=.28;g.add(ring);box(g,0,.48,0,.22,.45,.22,color);box(g,-.5,.55,0,.2,.12,.2,color)}scene.add(g);const maxHp=kind==='sentry'?100:kind==='dispenser'?130:100;metal-=buildCost;buildings.push({mesh:g,pos:new THREE.Vector3(pos.x,0,pos.z),side:team,hp:maxHp,maxHp,level:1,kind,next:clock,lastHeal:clock,cooldown:0,sizeX:kind==='sentry'?1.35:kind==='dispenser'?1.15:1.6,sizeZ:kind==='sentry'?1.15:kind==='dispenser'?.95:1.6});refreshNavBlocked();say(kind.toUpperCase()+' BUILT · LEVEL 1 · -'+buildCost+' METAL',1000);specialMode='';updatePda();buildViewWeapon();updateHud()}
function removeBuilding(){if(carriedBuilding){carriedBuilding.mesh.visible=true;carriedBuilding=null;if(carryBoxMesh){camera.remove(carryBoxMesh);carryBoxMesh=null}say('구조물 이동 취소',700);return}const candidates=buildings.filter(x=>x.side===team&&x.pos.distanceTo(player)<=9&&(buildChoice==='all'||(buildChoice==='teleporter'?x.kind.startsWith('teleporter'):x.kind===buildChoice))).sort((x,z)=>x.pos.distanceTo(player)-z.pos.distanceTo(player));if(!candidates.length){say('NO MATCHING FRIENDLY BUILDING NEARBY',850);return}const targets=buildChoice==='all'?candidates:[candidates[0]];for(const item of targets){if(item.sparkGroup)scene.remove(item.sparkGroup);scene.remove(item.mesh);buildings=buildings.filter(x=>x!==item)}refreshNavBlocked();say(targets.length>1?'BUILDINGS DISMANTLED':'BUILDING DISMANTLED',750);specialMode='';updatePda();buildViewWeapon()}
function spawnExplosionVisual(pos,color=0xff8a32,radius=2.2){const mesh=new THREE.Mesh(new THREE.SphereGeometry(1,12,10),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.78,depthWrite:false}));mesh.position.copy(pos);mesh.scale.setScalar(.35);scene.add(mesh);burnEffects.push({mesh,life:.38,explosion:true,maxLife:.38,maxScale:radius});for(let i=0;i<7;i++){const spark=new THREE.Mesh(new THREE.SphereGeometry(.07+Math.random()*.06,5,4),mat(i%2?0xffd56b:color));spark.position.copy(pos).add(new THREE.Vector3((Math.random()-.5)*.7,(Math.random()-.5)*.7,(Math.random()-.5)*.7));scene.add(spark);burnEffects.push({mesh:spark,life:.18+Math.random()*.16})}}
function damageBuilding(b,amount,attacker='ENEMY'){if(!b||!buildings.includes(b))return;b.hp=Math.max(0,b.hp-amount);playSfx('impact',b.pos,.22);if(b.hp<=0){playSfx('explosion',b.pos,.65);spawnExplosionVisual(b.pos.clone().add(new THREE.Vector3(0,.8,0)),b.side==='red'?0xff5147:0x438bff,2.6);if(b.sparkGroup)scene.remove(b.sparkGroup);scene.remove(b.mesh);buildings=buildings.filter(x=>x!==b);refreshNavBlocked();if(carriedBuilding===b){carriedBuilding=null;if(carryBoxMesh){camera.remove(carryBoxMesh);carryBoxMesh=null}}say('STRUCTURE DESTROYED',900);updatePda()}updateAimTarget()}
function repairBuilding(b){if(!b||b.hp>=b.maxHp)return false;const repair=Math.min(40,b.maxHp-b.hp),cost=Math.ceil(repair/2);if(metal<cost){say('철제가 부족합니다 · 필요 철제 '+cost,900);return true}metal-=cost;b.hp=Math.min(b.maxHp,b.hp+repair);say('구조물 수리 +'+repair+' HP · -'+cost+' 철제',900);updatePda();updateHud();return true}
function upgradeBuilding(b){if(b.sappedUntil){say('먼저 렌치로 교란기를 해체하세요',850);return}if(b.hp<b.maxHp&&repairBuilding(b))return;if(b.level>=3){say('BUILDING ALREADY LEVEL 3',700);return}const cost=200;if(metal<cost){say('NOT ENOUGH METAL · NEED '+cost,1000);return}metal-=cost;b.level++;const base=b.kind==='sentry'?100:b.kind==='dispenser'?130:100;b.maxHp=Math.round(base*Math.pow(1.55,b.level-1));b.hp=Math.min(b.maxHp,b.hp+Math.round(b.maxHp*.5));b.mesh.scale.setScalar(1+(b.level-1)*.13);b.mesh.traverse(o=>{if(o.isMesh)o.material=mat(b.level===2?0xb9c6cc:0xe7bd4b,.35)});box(b.mesh,0,b.level===2?1.65:1.9,0,b.level===2?1.3:1.55,.12,.12,mat(b.level===2?0xb9c6cc:0xffe17a,.3));say(b.kind.toUpperCase()+' UPGRADED · LEVEL '+b.level+' · -'+cost+' METAL',1000);updatePda();updateHud()}
function updateBuildings(dt){for(const b of [...buildings]){if(b.sappedUntil){if(b.sparkGroup){b.sparkGroup.rotation.y+=dt*.7;b.sparkGroup.children.forEach((s,i)=>{s.position.x+=(Math.random()-.5)*.06;s.position.y=.7+Math.random()*1.2;s.position.z+=(Math.random()-.5)*.06})}if(clock>=b.sappedUntil){playSfx('explosion',b.pos,.85);const blast=new THREE.Mesh(new THREE.SphereGeometry(1.7,12,8),new THREE.MeshBasicMaterial({color:0x65eaff,transparent:true,opacity:.75}));blast.position.copy(b.pos).add(new THREE.Vector3(0,1,0));scene.add(blast);setTimeout(()=>scene.remove(blast),220);if(b.sparkGroup)scene.remove(b.sparkGroup);scene.remove(b.mesh);buildings=buildings.filter(x=>x!==b);refreshNavBlocked();say('교란된 구조물 폭발!',950);updatePda();continue}if(clock>=(b.nextSpark||0)){b.nextSpark=clock+.24;const from=b.pos.clone().add(new THREE.Vector3((Math.random()-.5)*1.2,.5+Math.random()*1.4,(Math.random()-.5)*1.2)),to=from.clone().add(new THREE.Vector3((Math.random()-.5)*.8,Math.random()*.7,(Math.random()-.5)*.8));tracer(from,to,0x72eaff)}continue}if(b.kind==='dispenser'&&clock-b.lastHeal>1){b.lastHeal=clock;const range=6+(b.level-1)*2,heal=7+(b.level-1)*5;for(const t of bots)if(t.alive&&t.side===b.side)t.pos.distanceTo(b.pos)<range&&!t.sappedUntil&&(t.hp=Math.min(t.max,t.hp+heal));if(team===b.side&&player.distanceTo(b.pos)<range)health=Math.min(cls.hp,health+4+(b.level-1)*3)}if(b.kind==='teleporterEntrance'){const pair=buildings.find(x=>x.side===b.side&&x.kind==='teleporterExit'&&!x.sappedUntil);if(pair&&clock>=b.cooldown){if(team===b.side&&player.distanceTo(b.pos)<1.15){b.cooldown=clock+1.6;player.set(pair.pos.x+1,0,pair.pos.z);camera.position.set(player.x,groundHeightAt(player.x,player.z)+1.7+jumpHeight,player.z);say('TELEPORTED!',700)}for(const bot of bots){if(bot.alive&&bot.side===b.side&&bot.pos.distanceTo(b.pos)<1.15&&clock>=(bot.teleportAt||0)){bot.teleportAt=clock+5;bot.pos.set(pair.pos.x+1,0,pair.pos.z);bot.mesh.position.copy(bot.pos);bot.navPath=null;bot.navGoal=null}}b.cooldown=clock+.35}}if(b.kind==='sentry'&&setupRemaining<=0&&clock>=b.next){const range=18+(b.level-1)*6,targets=bots.filter(x=>x.alive&&x.side!==b.side&&x.pos.distanceTo(b.pos)<range).map(x=>({target:x,dist:x.pos.distanceTo(b.pos)}));if(team!==b.side&&player.distanceTo(b.pos)<range)targets.push({target:{isPlayer:true,pos:player,side:team},dist:player.distanceTo(b.pos)});targets.sort((x,z)=>x.dist-z.dist);const t=targets[0]?.target;if(t){b.next=clock+Math.max(.085,.18-(b.level-1)*.035);if(t.isPlayer)harmPlayer(9+(b.level-1)*5);else hurtBot(t,9+(b.level-1)*5,'SENTRY');tracer(b.pos.clone().add(new THREE.Vector3(0,1.2,0)),t.pos.clone().add(new THREE.Vector3(0,1.1,0)),b.side==='red'?0xff8071:0x7fc3ff)}}}}
