 if(['rocket','grenade','sticky'].includes(w.kind)){makeProjectile(origin.clone().addScaledVector(dir,.8),dir,'player',w.damage,w.speed,w.radius,team,w.kind);if(cls.id==='soldier'&&w.kind==='rocket'&&(keys.ControlLeft||keys.ControlRight)&&keys.Space&&pitch<-.18){vy=15.2;jumpHeight=Math.max(jumpHeight,.1);onGround=false;jumpCount=1;jumpPressed=false;health=Math.max(1,health-8);say('ROCKET JUMP! · BOOST',850)}}
